//! Reference security map checksums (generated by running the reference
//! server's map module) for real maps. The maps are not in this repository: set
//! `OSS_MAP_DIRS` to directories containing them; maps not found are skipped.

use std::path::{Path, PathBuf};

use oss_formats::{Level, TileGrid};
use oss_proto::checksum::{crc32, map_checksum};

fn collect(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(rd) = std::fs::read_dir(dir) else {
        return;
    };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            collect(&p, out);
        } else if p.extension().is_some_and(|x| x.eq_ignore_ascii_case("lvl")) {
            out.push(p);
        }
    }
}

#[test]
fn map_checksum_vectors() {
    let Some(dirs) = std::env::var_os("OSS_MAP_DIRS") else {
        return;
    };
    let mut maps = Vec::new();
    for d in std::env::split_paths(&dirs) {
        collect(&d, &mut maps);
    }
    let text = include_str!("vectors/map-checksum.txt");
    let mut current: Option<(TileGrid, String)> = None;
    let mut checked = 0;
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let f: Vec<&str> = line.split_whitespace().collect();
        match f[0] {
            "map" => {
                let name = f[3];
                let want_crc = u32::from_str_radix(f[5], 16).unwrap();
                // Several copies may exist; use one with the right contents.
                current = maps
                    .iter()
                    .filter(|p| p.file_name().is_some_and(|n| n.eq_ignore_ascii_case(name)))
                    .map(|p| std::fs::read(p).unwrap())
                    .find(|d| crc32(d) == want_crc)
                    .map(|data| {
                        assert_eq!(data.len(), f[4].parse::<usize>().unwrap(), "{name} size");
                        (
                            Level::parse(&data).unwrap().server_tile_grid().0,
                            name.to_string(),
                        )
                    });
                if current.is_none() {
                    println!("skipping {name}: not found under OSS_MAP_DIRS");
                }
            }
            "tiles" => {
                if let Some((g, name)) = &current {
                    let n = g.cells().iter().filter(|&&t| t != 0).count();
                    assert_eq!(
                        n,
                        f[1].parse::<usize>().unwrap(),
                        "{name} expanded tile count"
                    );
                }
            }
            "checksum" => {
                if let Some((g, name)) = &current {
                    let key = u32::from_str_radix(f[1], 16).unwrap();
                    let want = u32::from_str_radix(f[2], 16).unwrap();
                    let got = map_checksum(key, |x, y| g.get(x as u32, y as u32));
                    assert_eq!(got, want, "{name} key {key:#x}");
                    checked += 1;
                }
            }
            other => panic!("unknown record {other}"),
        }
    }
    println!("checked {checked} map checksums");
}
